def _compact_envelope(source, target, changed, summary, config):
    """升级包五字段紧凑 JSON 串（无尾 LF），固定键序与字段类型。"""
    return json.dumps(
        {
            "源版本": source,
            "目标版本": target,
            "改变": changed,
            "摘要": summary,
            "配置": config,
        },
        ensure_ascii=False,
        separators=(",", ":"),
    )


